arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  /* Brand palette (OKLCH) */
+  --gaa-red: oklch(55% 0.22 25);
+  --gaa-red-2: oklch(50% 0.20 25);
+  --gaa-navy: oklch(33% 0.07 245);
+  --gaa-ink: oklch(20% 0.02 250);
+  --gaa-muted: oklch(50% 0.02 250);
+  --gaa-border: oklch(86% 0.01 250);
+  --gaa-surface: oklch(98% 0.01 250);
+  --gaa-surface-2: oklch(96% 0.01 250);
+  --gaa-warm: oklch(94% 0.02 80);
+
+  --shadow-sm: 0 1px 2px rgba(0,0,0,.08);
+  --shadow-md: 0 12px 30px rgba(0,0,0,.12);
+  --radius-sm: 12px;
+  --radius-md: 16px;
+  --radius-lg: 22px;
+
+  --container: 1180px;
+  --gutter: 20px;
+  --focus: 2px solid oklch(70% 0.16 25);
+
+  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Inter, "Helvetica Neue", Arial, "Noto Sans", "Liberation Sans", sans-serif;
+}
+
+*{box-sizing:border-box}
+html{scroll-behavior:smooth}
+body{
+  margin:0;
+  font-family:var(--font-sans);
+  color:var(--gaa-ink);
+  background:linear-gradient(180deg, var(--gaa-surface), var(--gaa-warm));
+}
+
+a{color:inherit}
+.sr-only{
+  position:absolute;
+  width:1px;height:1px;
+  padding:0;margin:-1px;
+  overflow:hidden;clip:rect(0,0,0,0);
+  border:0;
+}
+
+.container{
+  max-width:var(--container);
+  margin:0 auto;
+  padding:0 var(--gutter);
+}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:12px;
+  background:var(--gaa-surface);
+  color:var(--gaa-ink);
+  padding:10px 12px;
+  border-radius:10px;
+  box-shadow:var(--shadow-sm);
+  z-index:9999;
+}
+.skip-link:focus{left:12px; outline:var(--focus)}
+
+/* Header */
+.header{
+  position:sticky;
+  top:0;
+  z-index:1200;
+  background:color-mix(in oklch, var(--gaa-surface) 88%, white 12%);
+  border-bottom:1px solid var(--gaa-border);
+  backdrop-filter:saturate(140%) blur(10px);
+}
+.header__bar{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:14px;
+  padding:12px 0;
+}
+.brand{
+  display:flex;
+  align-items:center;
+  gap:12px;
+  text-decoration:none;
+}
+.brand__mark{
+  width:40px;height:40px;
+  border-radius:14px;
+  background:radial-gradient(120% 120% at 20% 20%, oklch(70% 0.18 25), var(--gaa-red));
+  box-shadow:0 10px 24px rgba(196, 30, 58, .25);
+  position:relative;
+}
+.brand__mark::after{
+  content:"";
+  position:absolute;
+  inset:10px;
+  border-radius:10px;
+  background:color-mix(in oklch, white 84%, var(--gaa-red) 16%);
+  clip-path:polygon(38% 0, 62% 0, 62% 38%, 100% 38%, 100% 62%, 62% 62%, 62% 100%, 38% 100%, 38% 62%, 0 62%, 0 38%, 38% 38%);
+}
+.brand__name{line-height:1}
+.brand__name strong{display:block; font-size:14px; letter-spacing:.2px}
+.brand__name span{display:block; font-size:12px; color:var(--gaa-muted)}
+
+.nav{
+  display:flex;
+  align-items:center;
+  gap:18px;
+}
+.nav__links{
+  display:flex;
+  align-items:center;
+  gap:14px;
+}
+.nav__links a{
+  text-decoration:none;
+  color:color-mix(in oklch, var(--gaa-ink) 84%, var(--gaa-navy));
+  font-weight:600;
+  font-size:13px;
+  padding:10px 10px;
+  border-radius:12px;
+}
+.nav__links a:hover{background:var(--gaa-surface-2)}
+.utility{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  color:var(--gaa-muted);
+  font-size:12px;
+}
+.utility a{color:inherit; text-decoration:none}
+.utility a:hover{text-decoration:underline}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:8px;
+  padding:12px 14px;
+  border-radius:999px;
+  border:1px solid transparent;
+  font-weight:700;
+  cursor:pointer;
+  text-decoration:none;
+  transition:transform .12s ease, box-shadow .12s ease, background-color .12s ease, border-color .12s ease;
+  user-select:none;
+}
+.btn:active{transform:translateY(1px)}
+.btn:focus-visible{outline:var(--focus); outline-offset:3px}
+.btn--primary{
+  background:var(--gaa-red);
+  color:white;
+  box-shadow:0 10px 24px rgba(196, 30, 58, .22);
+}
+.btn--primary:hover{background:var(--gaa-red-2)}
+.btn--secondary{
+  background:color-mix(in oklch, var(--gaa-surface) 92%, var(--gaa-navy));
+  color:var(--gaa-navy);
+  border-color:color-mix(in oklch, var(--gaa-border) 72%, var(--gaa-navy));
+}
+.btn--secondary:hover{background:var(--gaa-surface-2)}
+.btn--ghost{
+  background:transparent;
+  border-color:var(--gaa-border);
+  color:var(--gaa-ink);
+}
+.btn--ghost:hover{background:var(--gaa-surface-2)}
+
+.hamburger{
+  display:none;
+  align-items:center;
+  justify-content:center;
+  width:44px;height:44px;
+  border-radius:14px;
+  border:1px solid var(--gaa-border);
+  background:var(--gaa-surface);
+  cursor:pointer;
+}
+.hamburger:focus-visible{outline:var(--focus); outline-offset:3px}
+
+/* Mobile drawer */
+.drawer-backdrop{
+  position:fixed;
+  inset:0;
+  background:rgba(0,0,0,.35);
+  opacity:0;
+  pointer-events:none;
+  transition:opacity .18s ease;
+  z-index:1400;
+}
+.drawer{
+  position:fixed;
+  top:0;right:0;
+  height:100%;
+  width:min(92vw, 380px);
+  background:var(--gaa-surface);
+  border-left:1px solid var(--gaa-border);
+  box-shadow:var(--shadow-md);
+  transform:translateX(102%);
+  transition:transform .22s ease;
+  z-index:1500;
+  display:flex;
+  flex-direction:column;
+}
+.drawer__head{display:flex; align-items:center; justify-content:space-between; padding:14px; border-bottom:1px solid var(--gaa-border)}
+.drawer__body{padding:14px; display:flex; flex-direction:column; gap:8px}
+.drawer__body a{
+  text-decoration:none;
+  font-weight:700;
+  padding:12px 12px;
+  border-radius:14px;
+  background:var(--gaa-surface-2);
+}
+.drawer__body a:focus-visible{outline:var(--focus); outline-offset:3px}
+.drawer__utility{margin-top:6px; padding-top:10px; border-top:1px dashed var(--gaa-border); color:var(--gaa-muted); font-size:13px}
+.drawer-open .drawer-backdrop{opacity:1; pointer-events:auto}
+.drawer-open .drawer{transform:translateX(0)}
+
+/* Sections */
+section{padding:64px 0}
+.section__kicker{
+  display:inline-flex;
+  align-items:center;
+  gap:10px;
+  padding:8px 12px;
+  border-radius:999px;
+  background:color-mix(in oklch, var(--gaa-surface-2) 88%, var(--gaa-red));
+  border:1px solid var(--gaa-border);
+  font-weight:800;
+  font-size:12px;
+  color:color-mix(in oklch, var(--gaa-ink) 76%, var(--gaa-red));
+}
+.section__title{font-size:34px; letter-spacing:-.02em; margin:14px 0 10px}
+.section__lead{max-width:70ch; color:color-mix(in oklch, var(--gaa-muted) 80%, var(--gaa-ink)); font-size:16px; line-height:1.7; margin:0}
+
+/* Hero */
+.hero{padding:36px 0 22px}
+.hero__grid{
+  display:grid;
+  grid-template-columns: 1.2fr .8fr;
+  gap:26px;
+  align-items:stretch;
+}
+.hero__card{
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:linear-gradient(180deg, color-mix(in oklch, white 84%, var(--gaa-surface)), var(--gaa-surface-2));
+  box-shadow:var(--shadow-sm);
+  padding:26px;
+  position:relative;
+  overflow:hidden;
+}
+.hero__card::before{
+  content:"";
+  position:absolute;
+  inset:-220px -160px auto auto;
+  width:520px;height:520px;
+  background:radial-gradient(circle at 30% 30%, color-mix(in oklch, var(--gaa-red) 60%, white), transparent 62%);
+  transform:rotate(10deg);
+  opacity:.9;
+}
+.hero__title{font-size:46px; line-height:1.05; margin:0 0 10px; letter-spacing:-.03em; position:relative}
+.hero__subtitle{position:relative; margin:0; color:color-mix(in oklch, var(--gaa-muted) 74%, var(--gaa-ink)); line-height:1.7; font-size:16px; max-width:70ch}
+.hero__actions{position:relative; display:flex; flex-wrap:wrap; gap:12px; margin-top:18px}
+
+.hero__aside{
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:linear-gradient(180deg, color-mix(in oklch, var(--gaa-navy) 12%, white), var(--gaa-surface));
+  box-shadow:var(--shadow-sm);
+  overflow:hidden;
+  display:flex;
+  flex-direction:column;
+}
+.hero__image{
+  height:220px;
+  background:
+    linear-gradient(120deg, rgba(27,58,92,.28), rgba(196,30,58,.18)),
+    url("assets/hero.jpg");
+  background-size:cover;
+  background-position:center;
+}
+.hero__aside-body{padding:18px}
+.trust{
+  display:grid;
+  grid-template-columns: 1fr 1fr;
+  gap:10px;
+}
+.pill{
+  border:1px solid var(--gaa-border);
+  background:var(--gaa-surface);
+  border-radius:999px;
+  padding:10px 12px;
+  font-weight:800;
+  font-size:12px;
+  color:color-mix(in oklch, var(--gaa-ink) 78%, var(--gaa-navy));
+}
+
+/* Mission */
+.mission{
+  display:grid;
+  grid-template-columns: 1fr 1fr;
+  gap:22px;
+  align-items:start;
+}
+.card{
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:var(--gaa-surface);
+  box-shadow:var(--shadow-sm);
+}
+.card__body{padding:22px}
+.quote{
+  margin:0;
+  padding:22px;
+  background:linear-gradient(135deg, color-mix(in oklch, var(--gaa-red) 12%, white), var(--gaa-surface));
+  border-radius:var(--radius-lg);
+  border:1px solid var(--gaa-border);
+  line-height:1.8;
+}
+.quote strong{color:color-mix(in oklch, var(--gaa-ink) 78%, var(--gaa-red))}
+
+/* Impact */
+.stats{
+  display:grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap:14px;
+  margin-top:18px;
+}
+.stat{
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:linear-gradient(180deg, var(--gaa-surface), var(--gaa-surface-2));
+  box-shadow:var(--shadow-sm);
+  padding:18px;
+}
+.stat__value{font-size:30px; font-weight:900; letter-spacing:-.02em}
+.stat__label{margin-top:6px; color:var(--gaa-muted); font-weight:700; font-size:13px; line-height:1.35}
+.stat__value span{color:var(--gaa-red)}
+
+/* Programs accordion */
+.accordion{
+  display:grid;
+  grid-template-columns: 1.1fr .9fr;
+  gap:16px;
+  margin-top:18px;
+}
+.accordion__list{display:flex; flex-direction:column; gap:10px}
+.acc-item{border:1px solid var(--gaa-border); border-radius:var(--radius-md); background:var(--gaa-surface); overflow:hidden; box-shadow:var(--shadow-sm)}
+.acc-btn{
+  width:100%;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:12px;
+  padding:16px 16px;
+  background:transparent;
+  border:0;
+  cursor:pointer;
+  text-align:left;
+}
+.acc-btn:focus-visible{outline:var(--focus); outline-offset:-3px}
+.acc-title{font-weight:900; letter-spacing:-.01em}
+.acc-meta{color:var(--gaa-muted); font-weight:700; font-size:13px}
+.acc-icon{
+  width:38px;height:38px;
+  border-radius:14px;
+  border:1px solid var(--gaa-border);
+  background:var(--gaa-surface-2);
+  display:grid;
+  place-items:center;
+  flex:0 0 auto;
+}
+.acc-panel{
+  max-height:0;
+  overflow:hidden;
+  transition:max-height .28s ease;
+}
+.acc-panel__inner{padding:0 16px 16px}
+.acc-panel p{margin:0; color:color-mix(in oklch, var(--gaa-muted) 74%, var(--gaa-ink)); line-height:1.75}
+
+.programs__aside{border:1px solid var(--gaa-border); border-radius:var(--radius-lg); background:linear-gradient(135deg, color-mix(in oklch, var(--gaa-navy) 10%, white), var(--gaa-surface)); box-shadow:var(--shadow-sm); overflow:hidden}
+.programs__aside .card__body{padding:18px}
+.mini-list{display:flex; flex-direction:column; gap:10px; margin-top:12px}
+.mini{
+  display:flex;
+  gap:12px;
+  align-items:flex-start;
+  padding:12px 12px;
+  border-radius:14px;
+  background:var(--gaa-surface);
+  border:1px solid var(--gaa-border);
+}
+.mini strong{display:block}
+.mini span{display:block; color:var(--gaa-muted); font-weight:700; font-size:12px; line-height:1.35; margin-top:2px}
+
+/* Get involved */
+.cta-grid{
+  display:grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap:14px;
+  margin-top:18px;
+}
+.cta{
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:var(--gaa-surface);
+  box-shadow:var(--shadow-sm);
+  padding:18px;
+  display:flex;
+  flex-direction:column;
+  gap:10px;
+}
+.cta h3{margin:0; font-size:18px; letter-spacing:-.01em}
+.cta p{margin:0; color:color-mix(in oklch, var(--gaa-muted) 76%, var(--gaa-ink)); line-height:1.7}
+.cta .btn{margin-top:6px; align-self:flex-start}
+
+/* News carousel */
+.carousel{
+  margin-top:18px;
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:var(--gaa-surface);
+  box-shadow:var(--shadow-sm);
+  overflow:hidden;
+}
+.carousel__head{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:14px;
+  padding:14px 16px;
+  border-bottom:1px solid var(--gaa-border);
+}
+.carousel__controls{display:flex; gap:10px}
+.icon-btn{
+  width:44px;height:44px;
+  display:grid;
+  place-items:center;
+  border-radius:14px;
+  border:1px solid var(--gaa-border);
+  background:var(--gaa-surface);
+  cursor:pointer;
+}
+.icon-btn:hover{background:var(--gaa-surface-2)}
+.icon-btn:focus-visible{outline:var(--focus); outline-offset:3px}
+.icon-btn[disabled]{opacity:.5; cursor:not-allowed}
+
+.carousel__viewport{overflow:hidden}
+.carousel__track{
+  display:flex;
+  gap:14px;
+  padding:16px;
+  transform:translateX(0);
+  transition:transform .32s ease;
+}
+.news-card{
+  flex:0 0 calc((100% - 28px)/3);
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:linear-gradient(180deg, var(--gaa-surface), var(--gaa-surface-2));
+  overflow:hidden;
+  min-height:270px;
+  display:flex;
+  flex-direction:column;
+}
+.news-card__img{height:130px; background:#ddd; background-size:cover; background-position:center}
+.news-card__body{padding:14px; display:flex; flex-direction:column; gap:8px; flex:1}
+.news-card__body h3{margin:0; font-size:16px; letter-spacing:-.01em}
+.news-card__body p{margin:0; color:color-mix(in oklch, var(--gaa-muted) 78%, var(--gaa-ink)); line-height:1.7; font-size:13px}
+.news-card__tag{display:inline-flex; align-items:center; gap:8px; font-weight:900; font-size:11px; color:color-mix(in oklch, var(--gaa-ink) 72%, var(--gaa-navy));}
+
+/* Donate CTA */
+.donate{
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:linear-gradient(135deg, color-mix(in oklch, var(--gaa-red) 10%, white), var(--gaa-surface));
+  box-shadow:var(--shadow-sm);
+  padding:22px;
+  display:grid;
+  grid-template-columns: 1.1fr .9fr;
+  gap:18px;
+  align-items:start;
+}
+.donate p{margin:0; color:color-mix(in oklch, var(--gaa-muted) 78%, var(--gaa-ink)); line-height:1.75}
+.impact-table{width:100%; border-collapse:collapse; margin-top:12px; font-size:13px}
+.impact-table th, .impact-table td{padding:10px 10px; border-bottom:1px solid var(--gaa-border); text-align:left}
+.impact-table th{color:var(--gaa-muted); font-weight:900; font-size:12px; letter-spacing:.02em; text-transform:uppercase}
+.donate__actions{display:flex; gap:12px; flex-wrap:wrap; margin-top:14px}
+
+/* Footer */
+.footer{padding:54px 0 28px; border-top:1px solid var(--gaa-border); background:color-mix(in oklch, var(--gaa-surface) 84%, white 16%)}
+.footer__grid{display:grid; grid-template-columns: 1.4fr 1fr 1fr 1fr; gap:16px}
+.footer h4{margin:0 0 10px; font-size:13px; color:var(--gaa-muted); text-transform:uppercase; letter-spacing:.05em}
+.footer a{display:block; text-decoration:none; color:color-mix(in oklch, var(--gaa-ink) 80%, var(--gaa-navy)); font-weight:700; padding:6px 0; font-size:13px}
+.footer a:hover{text-decoration:underline}
+.footer__meta{margin-top:18px; display:flex; flex-wrap:wrap; justify-content:space-between; gap:12px; color:var(--gaa-muted); font-size:12px}
+.social{display:flex; gap:10px; flex-wrap:wrap}
+.social a{display:inline-flex; padding:8px 10px; border-radius:999px; border:1px solid var(--gaa-border); background:var(--gaa-surface); text-decoration:none}
+.social a:hover{background:var(--gaa-surface-2)}
+
+/* Modal */
+.modal-backdrop{
+  position:fixed;
+  inset:0;
+  background:rgba(0,0,0,.45);
+  opacity:0;
+  pointer-events:none;
+  transition:opacity .18s ease;
+  z-index:1600;
+}
+.modal{
+  position:fixed;
+  inset:0;
+  display:grid;
+  place-items:center;
+  padding:16px;
+  z-index:1700;
+  pointer-events:none;
+}
+.modal__panel{
+  width:min(980px, 100%);
+  border-radius:var(--radius-lg);
+  border:1px solid var(--gaa-border);
+  background:var(--gaa-surface);
+  box-shadow:var(--shadow-md);
+  transform:translateY(12px) scale(.98);
+  opacity:0;
+  transition:transform .18s ease, opacity .18s ease;
+}
+.modal__head{display:flex; align-items:center; justify-content:space-between; gap:10px; padding:14px 16px; border-bottom:1px solid var(--gaa-border)}
+.modal__head h2{margin:0; font-size:16px}
+.modal__body{padding:16px; display:grid; grid-template-columns: 1.1fr .9fr; gap:16px}
+.modal__close{width:44px;height:44px}
+
+.donation{
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:linear-gradient(180deg, var(--gaa-surface), var(--gaa-surface-2));
+  padding:14px;
+}
+.donation h3{margin:0 0 10px; font-size:14px; color:var(--gaa-muted); text-transform:uppercase; letter-spacing:.06em}
+.amounts{display:grid; grid-template-columns: repeat(3, 1fr); gap:10px}
+.chip{
+  padding:12px 10px;
+  border-radius:14px;
+  border:1px solid var(--gaa-border);
+  background:var(--gaa-surface);
+  font-weight:900;
+  cursor:pointer;
+}
+.chip:hover{background:var(--gaa-surface-2)}
+.chip[aria-pressed="true"]{border-color:color-mix(in oklch, var(--gaa-red) 68%, var(--gaa-border)); box-shadow:0 12px 24px rgba(196, 30, 58, .16)}
+.field{margin-top:12px}
+.field label{display:block; font-weight:900; font-size:12px; letter-spacing:.03em; text-transform:uppercase; color:var(--gaa-muted)}
+.field input{
+  width:100%;
+  margin-top:8px;
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid var(--gaa-border);
+  font:inherit;
+}
+.field input:focus{outline:var(--focus); outline-offset:2px}
+.donation__actions{display:flex; gap:10px; flex-wrap:wrap; margin-top:14px}
+.help{
+  border:1px solid var(--gaa-border);
+  border-radius:var(--radius-lg);
+  background:linear-gradient(135deg, color-mix(in oklch, var(--gaa-navy) 10%, white), var(--gaa-surface));
+  padding:14px;
+}
+.help p{margin:0; color:color-mix(in oklch, var(--gaa-muted) 76%, var(--gaa-ink)); line-height:1.75}
+.help ul{margin:12px 0 0; padding-left:18px; color:color-mix(in oklch, var(--gaa-muted) 76%, var(--gaa-ink)); line-height:1.8}
+
+.modal-open .modal-backdrop{opacity:1; pointer-events:auto}
+.modal-open .modal{pointer-events:auto}
